import{RANK,int}from"/assets/logline.3085ab1b47b4.js";import{took}from"/assets/tick.d6ab0874d442.js";import{clock}from"/assets/when.2f5fea25ce95.js";const GAP_MS=6e4;const PLAN_GAP_MS=12e4;const MIN=3;const LIFE=new Set(["start","card","ready","end"]);const ROBOT=new Set(["robot_join","robot_leave","robot_moved"]);export function eventLevel(e){if(!e)return undefined;if(e.kind==="act_error"||e.kind==="error"||e.kind==="end"&&e.reason==="error")return"error";if(e.kind==="plan_error"&&e.failure==="permanent")return"error";if(e.kind==="act_slow"||e.kind==="refused"||e.kind==="platform"&&["oom","health_failed","restart","prints_truncated","prints_dropped","storage_full","batch_rerun"].includes(e.what)){return"warn"}return undefined}export function eventText(e){const text=String(e.text??e.line??"");const until=e.kind==="end"&&e.billed_until!=null?Number(e.billed_until):NaN;return Number.isFinite(until)?text.replace("billed up to this time",`billed up to ${clock(until*1e3,true)}`):text}export function classify(L,given){const ek=given&&given.ek;L.ek=LIFE.has(ek)?"life":ROBOT.has(ek)?"robot":ek||"user";L.ev=given&&given.ev||null;return L}const num=v=>v==null||v===""?NaN:Number(v);function slow(L){const ms=num(L.ev&&L.ev.ms);const budget=num(L.ev&&L.ev.budget_ms);return Number.isFinite(ms)&&Number.isFinite(budget)&&ms>budget}const runOf=L=>{const f=L.ev||{};return`${f.key||""}\0${f.session||""}`};const foldable=L=>RANK[L.level]<RANK.warn&&L.blk==null&&(L.ek==="user"||L.ek==="act"&&!(L.ev&&L.ev.count!=null)&&!slow(L));const mask=t=>String(t).replace(/\b[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+\b|\b(?=[0-9a-f]*\d)[0-9a-f]{4,}\b|\b[a-z]+-[0-9a-z]{4,}\b|-?\d+(?:\.\d+)?/gi,"#");export function fold(lines,opened=new Set){const groups=[];const open=new Map;const plans=new Map;const runsOf=src=>[...open.keys()].filter((id=>id.startsWith(`${src}\0`)));for(let i=0;i<lines.length;i++){const L=lines[i];L.grp=null;const src=L.src||"";if(L.ek==="plan"||L.ek==="plan_error"){const f=L.ev||{};const robot=String(f.robot??"");const failure=f.failure;const id=`${src}\0${robot}`;let g=plans.get(id);if(L.ek==="plan"||failure!=="permanent"){if(!g||L.t==null||g.t1==null||L.t-g.t1>PLAN_GAP_MS){g={kind:"plan",lines:[],src:src,robot:robot==="_"?"":robot,failed:0,missed:0};plans.set(id,g);groups.push(g)}g.lines.push(i);if(L.ek==="plan_error")g.missed+=1;if(g.t0==null)g.t0=L.t;if(L.t!=null)g.t1=L.t}if(L.ek==="plan_error"&&g)g.failed+=1;continue}if(foldable(L)){let id;let g;if(L.ek==="act"){id=`${src}\0a\0${runOf(L)}`;g=open.get(id);if(!g||L.t==null||g.t1==null||L.t-g.t1>GAP_MS){g={kind:"act",lines:[],src:src,key:L.ev&&L.ev.key||"",failed:0,slow:0};open.set(id,g);groups.push(g)}}else{const m=mask(L.text);id=`${src}\0u`;g=open.get(id);if(!g||g.mask!==m){g={kind:"user",lines:[],src:src,mask:m};open.set(id,g);groups.push(g)}}g.lines.push(i);if(g.t0==null)g.t0=L.t;if(L.t!=null)g.t1=L.t;continue}if(L.ek==="act_error"||L.ek==="act_slow"||L.ek==="act"&&slow(L)){const g=open.get(`${src}\0a\0${runOf(L)}`)||open.get(runsOf(src).find((id=>id.includes("\0a\0"))));if(g){if(L.ek==="act_error")g.failed+=1;else g.slow+=1}continue}for(const id of runsOf(src))open.delete(id)}const kept=groups.filter((g=>g.lines.length>=MIN));kept.forEach(((g,k)=>{g.from=g.lines[0];g.to=g.lines[g.lines.length-1];g.id=`${g.kind}:${lines[g.from].n}`;g.open=opened.has(g.id);for(const i of g.lines)lines[i].grp=k}));return kept}const ms=v=>`${v<10?v.toFixed(1):Math.round(v)} ms`;const whole=v=>`${Math.round(v)} ms`;function pct(xs,q){const i=(xs.length-1)*q;const lo=Math.floor(i);const hi=Math.min(lo+1,xs.length-1);return xs[lo]+(xs[hi]-xs[lo])*(i-lo)}export function summary(g,lines){const span=g.t0!=null&&g.t1!=null&&g.t1>g.t0?`over ${took((g.t1-g.t0)/1e3)}`:null;if(g.kind==="user")return{head:`×${int(g.lines.length)}`,rest:[lines[g.from].text,span].filter(Boolean).join(" · ")};if(g.kind==="plan"){const xs=g.lines.filter((i=>lines[i].ek==="plan")).map((i=>num(lines[i].ev&&lines[i].ev.ms))).filter(Number.isFinite).sort(((a,b)=>a-b));const done=g.lines.length-g.missed;const bits=[span];if(xs.length)bits.push(`p50 ${whole(pct(xs,.5))}`,`p95 ${whole(pct(xs,.95))}`);bits.push(`${int(g.failed)} failed`);if(g.robot)bits.push(`robot ${g.robot}`);return{head:`${int(done)} plan${done===1?"":"s"}`,rest:bits.filter(Boolean).join(" · ")}}const col=key=>g.lines.map((i=>num(lines[i].ev&&lines[i].ev[key]))).filter(Number.isFinite).sort(((a,b)=>a-b));const total=col("ms");const legs=[["read","read_ms"],["queue","queue_ms"],["batch","batch_ms"]].map((([word,key])=>[word,col(key)])).filter((([,xs])=>xs.length));const bits=[span];if(total.length)bits.push(`p50 ${ms(pct(total,.5))}`,`p95 ${ms(pct(total,.95))}`,`max ${ms(total[total.length-1])}`);for(const[word,xs]of legs)bits.push(`${word} p50 ${ms(pct(xs,.5))}`);bits.push(`${int(g.failed)} failed`);if(g.slow)bits.push(`${int(g.slow)} slow`);if(g.key)bits.push(`key ${g.key}`);return{head:`${int(g.lines.length)} act${g.lines.length===1?"":"s"}`,rest:bits.filter(Boolean).join(" · ")}}